import React, { useReducer, useState } from 'react'
import BetterDatePicker from '../BetterDatePicker/BetterDatePicker'
import Button from '../Button/Button'
import { Serve, Globe, Place } from '../icons'
import Menu from '../Menu/Menu'
import TextInput from '../TextInput/TextInput'
import Typography from '../Typography/Typography'
import type { DialogProps } from './Dialog'
import Dialog, { Backdrops, Constraints } from './Dialog'

const backdrops = {
  None: undefined,
  'Backdrops.Dark': Backdrops.Dark,
  'Backdrops.Light': Backdrops.Light,
}

const constraints = {
  None: undefined,
  'Constraints.Default': Constraints.Default,
  'Constraints.Padded': Constraints.Padded,
  'Constraints.Screen': Constraints.Screen,
}

export default {
  title: 'Components/Dialog',
  component: Dialog,
  argTypes: {
    actionLabels: {
      control: { type: 'object' },
    },
    header: {
      control: { type: 'text' },
    },
    content: {
      control: { type: 'text' },
    },
    backdrop: {
      control: { type: 'select' },
      options: Object.keys(backdrops),
      mapping: backdrops,
    },
    constraint: {
      control: { type: 'select' },
      options: Object.keys(constraints),
      mapping: constraints,
    },
  },
  args: {
    header: "Use Google's location service",
    content: `Let Google help apps determine location. This means sending
  anonymous location data to Google, even when no apps are running.`,
    actionLabels: ['Disagree', 'Agree'],
  },
}

const flipState = (state: boolean) => !state

function Template(
  args: DialogProps & {
    actionLabels: string[]
    content: string
    header: string
  },
): JSX.Element {
  const [open, setOpen] = useReducer(flipState, false)

  const props = {
    ...args,
    actionLabels: undefined,
    header: undefined,
  }

  return (
    <>
      <Button onClick={setOpen} variant="outlined">
        Open Alert
      </Button>
      <Dialog {...props} onDismiss={setOpen} open={open}>
        {args.header ? <Dialog.Header>{args.header}</Dialog.Header> : null}
        <Dialog.Content>{args.content}</Dialog.Content>
        {args.actionLabels.length ? (
          <Dialog.Actions>
            {args.actionLabels.map((label) => (
              <Button
                color="primary"
                key={label}
                onClick={setOpen}
                size="small"
                variant="text"
              >
                {label}
              </Button>
            ))}
          </Dialog.Actions>
        ) : null}
      </Dialog>
    </>
  )
}

export const Default = {
  render: Template,
}

