/**
 * Reproduction for a BetterDatePicker rendered inside a Dialog. The calendar
 * popover is portaled outside the dialog, so it has to survive the dialog's
 * focus lock, scroll lock, and backdrop click handling
 */
export function WithDatePicker(): JSX.Element {
  const [open, setOpen] = useReducer(flipState, false)
  const [endDate, setEndDate] = useState<Date | null>(new Date())

  return (
    <>
      <Button onClick={setOpen} variant="outlined">
        Open Recurrence
      </Button>
      <Dialog onDismiss={setOpen} open={open}>
        <Dialog.Header>Recurrence</Dialog.Header>
        <Dialog.Content>
          <div className="flex w-93 flex-col space-y-4 py-4">
            <Typography variant="body2">
              Click the End date field. The calendar should open and stay open
              until a day is chosen or you click away from it.
            </Typography>
            <div className="flex space-x-3">
              <div className="w-32">
                <TextInput
                  defaultValue="1"
                  label="Occurrences"
                  type="number"
                  variant="filled"
                />
              </div>
              <BetterDatePicker
                displayFormat="text"
                label="End date"
                name="endDate"
                onChange={setEndDate}
                value={endDate}
                variant="filled"
              />
            </div>
          </div>
        </Dialog.Content>
        <Dialog.Actions>
          <Button color="primary" onClick={setOpen} size="small" variant="text">
            Save
          </Button>
        </Dialog.Actions>
      </Dialog>
    </>
  )
}
